const sales = [12, 18, 9, 22, 15];
nb.set('sales', sales);
nb.set('sales_summary', {
  count: sales.length,
  total: sales.reduce((a, b) => a + b, 0),
  average: sales.reduce((a, b) => a + b, 0) / sales.length
});
console.log('Saved sales and sales_summary from JS');

const peak = nb.get('sales_peak');
const summary = nb.get('sales_summary');
const rows = nb.get('sales').map((value, index) => ({ day: index + 1, value }));
return {
  title: 'Round-trip data flow',
  peak,
  average: Number(summary.average.toFixed(2)),
  rows
};
